/* Return the glyph bitmap for a printable ASCII character. */
const uint8_t *Font_GetGlyph(const FontDef *font, char character)
{
    uint8_t c = (uint8_t)character;

    if (c < 32U || c > 126U)
    {
        c = (uint8_t)'?';
    }

    uint16_t bytes_per_glyph =
        (uint16_t)font->height * (uint16_t)font->bytes_per_row;

    return &font->data[(uint16_t)(c - 32U) * bytes_per_glyph];
}
